@@ -0,0 +1,435 @@
+// Package sqlite is the app's Store over a SQLite file at
+// $DATA_DIR/links.db, on modernc.org/sqlite (pure Go, no cgo). The schema
+// lives in the .sql files embedded from this directory, applied in name
+// order and remembered in schema_migrations.
+package sqlite
+
+import (
+	"context"
+	"database/sql"
+	"embed"
+	"errors"
+	"fmt"
+	"io/fs"
+	"sort"
+	"strings"
+	"time"
+
+	_ "modernc.org/sqlite"
+
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
+)
+
+//go:embed *.sql
+var migrations embed.FS
+
+// DB is store.Store over one SQLite file.
+type DB struct {
+	db *sql.DB
+}
+
+// Open prepares the database at path (its directory must exist), applies
+// the pending migrations and returns it. It keeps a single connection:
+// SQLite takes one writer at a time, and with it a count-then-insert never
+// loses a click to another.
+func Open(path string) (*DB, error) {
+	dsn := "file:" + path + "?_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)&_pragma=synchronous(FULL)"
+	sqlDB, err := sql.Open("sqlite", dsn)
+	if err != nil {
+		return nil, fmt.Errorf("sqlite: open %s: %w", path, err)
+	}
+	sqlDB.SetMaxOpenConns(1)
+	sqlDB.SetConnMaxLifetime(0)
+	if _, err := sqlDB.Exec(`PRAGMA user_version`); err != nil {
+		_ = sqlDB.Close()
+		return nil, fmt.Errorf("sqlite: reach %s: %w", path, err)
+	}
+	d := &DB{db: sqlDB}
+	ctx := context.Background()
+	if err := d.migrate(ctx); err != nil {
+		_ = d.Close()
+		return nil, err
+	}
+	return d, nil
+}
+
+// Close releases the database.
+func (d *DB) Close() error { return d.db.Close() }
+
+func (d *DB) migrate(ctx context.Context) error {
+	if _, err := d.db.ExecContext(ctx,
+		`CREATE TABLE IF NOT EXISTS schema_migrations (
+			name TEXT PRIMARY KEY,
+			applied_at TEXT NOT NULL
+		)`); err != nil {
+		return fmt.Errorf("sqlite: schema_migrations: %w", err)
+	}
+	names, err := fs.Glob(migrations, "*.sql")
+	if err != nil {
+		return fmt.Errorf("sqlite: read migrations: %w", err)
+	}
+	sort.Strings(names)
+	done := map[string]bool{}
+	rows, err := d.db.QueryContext(ctx, `SELECT name FROM schema_migrations`)
+	if err != nil {
+		return fmt.Errorf("sqlite: pending migrations: %w", err)
+	}
+	for rows.Next() {
+		var n string
+		if err := rows.Scan(&n); err != nil {
+			_ = rows.Close()
+			return fmt.Errorf("sqlite: scan migration: %w", err)
+		}
+		done[n] = true
+	}
+	if err := rows.Err(); err != nil {
+		_ = rows.Close()
+		return fmt.Errorf("sqlite: migrations: %w", err)
+	}
+	_ = rows.Close()
+
+	for _, name := range names {
+		if done[name] {
+			continue
+		}
+		stmts, err := migrations.ReadFile(name)
+		if err != nil {
+			return fmt.Errorf("sqlite: read %s: %w", name, err)
+		}
+		tx, err := d.db.BeginTx(ctx, nil)
+		if err != nil {
+			return fmt.Errorf("sqlite: begin %s: %w", name, err)
+		}
+		for _, stmt := range splitStatements(string(stmts)) {
+			if _, err := tx.ExecContext(ctx, stmt); err != nil {
+				_ = tx.Rollback()
+				return fmt.Errorf("sqlite: apply %s: %w", name, err)
+			}
+		}
+		if _, err := tx.ExecContext(ctx,
+			`INSERT INTO schema_migrations (name, applied_at) VALUES (?, ?)`,
+			name, time.Now().UTC().Format(time.RFC3339)); err != nil {
+			_ = tx.Rollback()
+			return fmt.Errorf("sqlite: record %s: %w", name, err)
+		}
+		if err := tx.Commit(); err != nil {
+			return fmt.Errorf("sqlite: commit %s: %w", name, err)
+		}
+	}
+	return nil
+}
+
+// splitStatements cuts a migration file into the statements of its ";"
+// separated DDL, dropping the comments.
+func splitStatements(src string) []string {
+	var out []string
+	for _, part := range strings.Split(src, ";") {
+		lines := strings.Split(part, "\n")
+		for i, line := range lines {
+			if j := strings.Index(line, "--"); j >= 0 {
+				lines[i] = line[:j]
+			}
+		}
+		if s := strings.TrimSpace(strings.Join(lines, "\n")); s != "" {
+			out = append(out, s)
+		}
+	}
+	return out
+}
+
+func nowUTC() time.Time { return time.Now().UTC() }
+
+func formatTime(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }
+
+func dayOf(t time.Time) string { return t.UTC().Format("2006-01-02") }
+
+// scanUser reads the columns every user query selects.
+func scanUser(scan func(dest ...any) error) (store.User, error) {
+	var u store.User
+	if err := scan(&u.ID, &u.Email, &u.PasswordHash, &u.CreatedAt); err != nil {
+		return store.User{}, err
+	}
+	return u, nil
+}
+
+const userColumns = `id, email, password_hash, created_at`
+
+// CreateUser stores a new account; an email that already has one answers
+// store.ErrDuplicate.
+func (d *DB) CreateUser(ctx context.Context, email, passwordHash string) (*store.User, error) {
+	email = strings.TrimSpace(email)
+	if email == "" || passwordHash == "" {
+		return nil, fmt.Errorf("sqlite: CreateUser: %w", store.ErrInvalid)
+	}
+	res, err := d.db.ExecContext(ctx,
+		`INSERT INTO users (email, password_hash, created_at) VALUES (?, ?, ?)`,
+		email, passwordHash, formatTime(nowUTC()))
+	if err != nil {
+		if isUnique(err) {
+			return nil, store.ErrDuplicate
+		}
+		return nil, fmt.Errorf("sqlite: create user: %w", err)
+	}
+	id, err := res.LastInsertId()
+	if err != nil {
+		return nil, fmt.Errorf("sqlite: created user id: %w", err)
+	}
+	return &store.User{ID: id, Em
